<template><SilkRoadWorkspace title="营销素材库"><ProjectStageNav :project-id="projectId" /><section class="page-head"><div><h1>项目营销素材</h1><p>统一管理商品主图、详情图、广告图、视频画面、口播音频和导出内容。</p></div><div><el-button @click="router.push(`/media/image?projectId=${projectId}`)">生成图片</el-button><el-button type="primary" @click="router.push(`/media/video?projectId=${projectId}`)">生成视频</el-button></div></section><div v-loading="loading" class="asset-grid"><article v-for="asset in assets" :key="asset.id"><div class="preview"><img v-if="asset.type==='image'" :src="asset.thumbnail_url||asset.url" :alt="asset.name" /><video v-else-if="asset.type==='video'" :src="asset.url" controls /><el-icon v-else><Headset /></el-icon></div><div><el-tag size="small">{{ typeLabel(asset.type) }}</el-tag><h2>{{ asset.name }}</h2><p>{{ asset.description||'项目营销素材' }}</p></div></article></div><el-empty v-if="!loading&&!assets.length" description="暂无项目素材"><el-button type="primary" @click="router.push(`/media/image?projectId=${projectId}`)">生成第一张营销素材图</el-button></el-empty></SilkRoadWorkspace></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{Headset}from'@element-plus/icons-vue';import{useRoute,useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import ProjectStageNav from '@/components/projects/ProjectStageNav.vue';import{projectAPI}from'@/api/project';const route=useRoute(),router=useRouter(),projectId=String(route.params.id),assets=ref<any[]>([]),loading=ref(false);const typeLabel=(t:string)=>({image:'营销图片',video:'营销视频',audio:'音乐 / 音效'}[t]||'素材');onMounted(async()=>{loading.value=true;try{assets.value=(await projectAPI.getAssets(projectId)).items||[]}finally{loading.value=false}})</script>
<style scoped>.page-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:22px}.page-head h1{font-size:29px;margin-bottom:7px}.page-head p{color:var(--text-secondary)}.asset-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:18px;min-height:120px}.asset-grid article{overflow:hidden;border:1px solid var(--border-primary);border-radius:18px;background:var(--bg-card)}.preview{height:175px;display:grid;place-items:center;background:var(--bg-muted);font-size:48px}.preview img,.preview video{width:100%;height:100%;object-fit:cover}.asset-grid article>div:last-child{padding:16px}.asset-grid h2{font-size:17px;margin:10px 0}.asset-grid p{color:var(--text-secondary)}@media(max-width:700px){.page-head{align-items:stretch;flex-direction:column;gap:15px}}</style>
